import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Texture } from 'three/webgpu';
import { Group, Mesh, PlaneGeometry, Vector3, Euler } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // plane geometry – use a generic size (7x6) as placeholder
  const width = 7;
  const height = 6;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // load texture asynchronously
  const texturePromise = ctx.textureLoader.loadTexture(
    config.imageUrl ?? config?.intent?.visualSpec?.imageUrl ?? ''
  );
  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
    // keep reference for cleanup
    plane.userData._texture = tex;
  });

  // apply rotation and scale if provided
  if (config.sceneRotation) {
    const rot = config.sceneRotation;
    plane.rotation.set(rot[0] ?? 0, rot[1] ?? 0, rot[2] ?? 0);
  }
  if (config.sceneScale) {
    const sc = config.sceneScale;
    plane.scale.set(sc[0] ?? 1, sc[1] ?? 1, sc[2] ?? 1);
  }

  // event handlers
  const timelines = [];

  const hoverEnter = () => {
    const tl = gsap.to(plane.position, {
      y: plane.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.to(plane.position, {
      y: plane.position.y - 0.15,
      duration: 0.4,
      ease: 'power2.in',
    });
    timelines.push(tl);
  };
  const clickHandler = () => {
    const tl = gsap.to(plane.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      onComplete: () => {
        gsap.to(plane.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.2,
          ease: 'power2.out',
        });
      },
    });
    timelines.push(tl);
    ctx.emit('hub-journal.select', {});
  };

  root.userData.handlers = {
    hover: {
      onEnter: hoverEnter,
      onLeave: hoverLeave,
    },
    click: clickHandler,
  };

  // cleanup
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();
    // dispose texture if loaded
    const tex = plane.userData._texture;
    if (tex && tex instanceof Texture) {
      tex.dispose();
    }
    // kill all GSAP timelines
    timelines.forEach((t) => t.kill());
  };

  return root;
}
